INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_SYRIAC','Classical Syriac Christianity',250,1300)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BROCK_LUMINOUS_EYE','secondary scholarship','Sebastian Brock, The Luminous Eye: The Spiritual World Vision of Saint Ephrem the Syrian (Cistercian Publications, 1992)','West Syriac symbolic theology; Ephrem and the Syriac patristic tradition'),
 ('SRC_BAUM_WINKLER_COTE','secondary scholarship','Wilhelm Baum & Dietmar W. Winkler, The Church of the East: A Concise History (Routledge, 2003)','East Syriac / Church of the East history and principal figures')
INSERT INTO _e VALUES
 ('ENT_SYR_FATHERS','Syriac Fathers and Doctors (collective)','collective','sanctified human','Syriac Christian','asceticism; biblical exegesis; liturgical poetry; mysticism','B','Collective hub for the Aramaic-speaking Fathers, poets and theologians of West and East Syriac Christianity; well attested across Brock and Baum-Winkler.'),
 ('ENT_SYR_EPHREM','Ephrem the Syrian','sanctified human','sanctified human','Syriac Christian','liturgical poetry; symbolic theology; anti-heresy hymnody','B','Deacon of Nisibis and Edessa (c.306-373), ''Harp of the Spirit'', greatest Syriac hymnographer; doctor of the universal church. Attested by his Madrashe and Brock''s study.'),
 ('ENT_SYR_APHRAHAT','Aphrahat the Persian Sage','sanctified human','sanctified human','Syriac Christian','biblical exegesis; ascetic theology','B','Early-4th-c. Persian author of the 23 Demonstrations, earliest major Syriac theologian, writing under Sasanian rule. Attested by his Demonstrations and Baum-Winkler.'),
 ('ENT_SYR_ISAAC_NINEVEH','Isaac of Nineveh (Isaac the Syrian)','sanctified human','sanctified human','Syriac Christian','ascetic mysticism; prayer; divine mercy','B','7th-c. East Syriac bishop of Nineveh and hermit whose Ascetical Homilies on mercy and prayer were read across Orthodox monasticism. Attested by his homilies and Baum-Winkler.'),
 ('ENT_SYR_JACOB_SERUGH','Jacob of Serugh','sanctified human','sanctified human','Syriac Christian','liturgical poetry; verse homily (memra)','B','West Syriac bishop (c.451-521), ''Flute of the Holy Spirit'', author of hundreds of metrical verse homilies. Attested by his memre and Brock.'),
 ('ENT_SYR_NARSAI','Narsai','sanctified human','sanctified human','Syriac Christian','verse homily; biblical exegesis; theological education','B','5th-c. East Syriac poet-theologian, ''Harp of the Spirit'' of the Church of the East, head of the School of Nisibis. Attested by his metrical homilies and Baum-Winkler.'),
 ('ENT_SYR_BABAI','Babai the Great','sanctified human','sanctified human','Syriac Christian','systematic theology; monastic reform; christology','B','East Syriac monk-theologian (c.551-628) who systematized Church-of-the-East dyophysite christology in his Book of the Union and reformed its monasteries. Attested by Baum-Winkler.'),
 ('ENT_SYR_BAR_HEBRAEUS','Bar Hebraeus (Gregory Abu al-Faraj)','sanctified human','sanctified human','Syriac Christian','polymathy; chronicle; theology; philosophy','B','13th-c. West Syriac (Syriac Orthodox) maphrian, polymath and chronicler, last great classical Syriac author. Attested by his Chronicle and Baum-Winkler.'),
 ('ENT_SYR_JOHN_EPHESUS','John of Ephesus','sanctified human','sanctified human','Syriac Christian','church history; hagiography; mission','B','6th-c. West Syriac (Miaphysite) bishop and historian, author of the Ecclesiastical History and Lives of the Eastern Saints. Attested by his historical works and Baum-Winkler.'),
 ('ENT_SYR_PHILOXENUS','Philoxenus of Mabbug','sanctified human','sanctified human','Syriac Christian','miaphysite theology; ascetic teaching; scripture revision','B','West Syriac bishop (c.440-523), leading Miaphysite theologian and ascetic writer, sponsor of the Philoxenian Syriac New Testament. Attested by his discourses and Baum-Winkler.'),
 ('ENT_SYR_BARDAISAN','Bardaisan of Edessa','sanctified human','sanctified human','Syriac Christian','early Syriac thought; cosmology; dialogue','C','Early Edessene Christian philosopher (154-222), author/subject of the Book of the Laws of Countries; later judged heterodox for astral-cosmological views. Foundational but contested figure; attested by Brock and the Dialogue.'),
 ('ENT_SYR_ADDAI','Addai (Thaddeus of Edessa)','sanctified human','sanctified human','Syriac Christian','apostolic mission; foundation of Edessan church','C','Apostle-evangelist of Edessa in the Abgar legend (Doctrine of Addai), traditional founder of Syriac Christianity. Legendary-traditional attestation via the Doctrine of Addai, cited in Baum-Winkler.');
