INSERT INTO _p VALUES
 ('ENT_SYR_FATHERS','PER_SYRIAC','Collective hub for the Aramaic-speaking Fathers, poets and theologians of West and East Syriac Christianity; well attested across Brock and Baum-Winkler.'),
 ('ENT_SYR_EPHREM','PER_SYRIAC','Deacon of Nisibis and Edessa (c.306-373), ''Harp of the Spirit'', greatest Syriac hymnographer; doctor of the universal church. Attested by his Madrashe and Brock''s study.'),
 ('ENT_SYR_APHRAHAT','PER_SYRIAC','Early-4th-c. Persian author of the 23 Demonstrations, earliest major Syriac theologian, writing under Sasanian rule. Attested by his Demonstrations and Baum-Winkler.'),
 ('ENT_SYR_ISAAC_NINEVEH','PER_SYRIAC','7th-c. East Syriac bishop of Nineveh and hermit whose Ascetical Homilies on mercy and prayer were read across Orthodox monasticism. Attested by his homilies and Baum-Winkler.'),
 ('ENT_SYR_JACOB_SERUGH','PER_SYRIAC','West Syriac bishop (c.451-521), ''Flute of the Holy Spirit'', author of hundreds of metrical verse homilies. Attested by his memre and Brock.'),
 ('ENT_SYR_NARSAI','PER_SYRIAC','5th-c. East Syriac poet-theologian, ''Harp of the Spirit'' of the Church of the East, head of the School of Nisibis. Attested by his metrical homilies and Baum-Winkler.'),
 ('ENT_SYR_BABAI','PER_SYRIAC','East Syriac monk-theologian (c.551-628) who systematized Church-of-the-East dyophysite christology in his Book of the Union and reformed its monasteries. Attested by Baum-Winkler.'),
 ('ENT_SYR_BAR_HEBRAEUS','PER_SYRIAC','13th-c. West Syriac (Syriac Orthodox) maphrian, polymath and chronicler, last great classical Syriac author. Attested by his Chronicle and Baum-Winkler.'),
 ('ENT_SYR_JOHN_EPHESUS','PER_SYRIAC','6th-c. West Syriac (Miaphysite) bishop and historian, author of the Ecclesiastical History and Lives of the Eastern Saints. Attested by his historical works and Baum-Winkler.'),
 ('ENT_SYR_PHILOXENUS','PER_SYRIAC','West Syriac bishop (c.440-523), leading Miaphysite theologian and ascetic writer, sponsor of the Philoxenian Syriac New Testament. Attested by his discourses and Baum-Winkler.'),
 ('ENT_SYR_BARDAISAN','PER_SYRIAC','Early Edessene Christian philosopher (154-222), author/subject of the Book of the Laws of Countries; later judged heterodox for astral-cosmological views. Foundational but contested figure; attested by Brock and the Dialogue.'),
 ('ENT_SYR_ADDAI','PER_SYRIAC','Apostle-evangelist of Edessa in the Abgar legend (Doctrine of Addai), traditional founder of Syriac Christianity. Legendary-traditional attestation via the Doctrine of Addai, cited in Baum-Winkler.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_SYR_EPHREM','member_of','ENT_SYR_FATHERS','high','Ephrem is the paradigmatic Syriac Father, the central figure of Brock''s study of the tradition.'),
 ('ENT_SYR_APHRAHAT','member_of','ENT_SYR_FATHERS','high','Aphrahat, the Persian Sage, is the earliest of the Syriac Fathers grouped in the collective.'),
 ('ENT_SYR_ISAAC_NINEVEH','member_of','ENT_SYR_FATHERS','high','Isaac of Nineveh is a principal East Syriac monastic Father.'),
 ('ENT_SYR_JACOB_SERUGH','member_of','ENT_SYR_FATHERS','high','Jacob of Serugh is a leading West Syriac poet-Father.'),
 ('ENT_SYR_NARSAI','member_of','ENT_SYR_FATHERS','high','Narsai is the chief poet-theologian of the East Syriac Fathers.'),
 ('ENT_SYR_BABAI','member_of','ENT_SYR_FATHERS','high','Babai the Great is a foundational East Syriac systematic theologian.'),
 ('ENT_SYR_BAR_HEBRAEUS','member_of','ENT_SYR_FATHERS','high','Bar Hebraeus is the last great classical Syriac Father and polymath.'),
 ('ENT_SYR_JOHN_EPHESUS','member_of','ENT_SYR_FATHERS','high','John of Ephesus, West Syriac historian-bishop, belongs to the Syriac Fathers.'),
 ('ENT_SYR_PHILOXENUS','member_of','ENT_SYR_FATHERS','high','Philoxenus of Mabbug is a major Miaphysite Syriac Father.'),
 ('ENT_SYR_BARDAISAN','member_of','ENT_SYR_FATHERS','medium','Bardaisan is an early Edessene Syriac thinker counted among the tradition''s foundational (if later contested) figures.'),
 ('ENT_SYR_ADDAI','member_of','ENT_SYR_FATHERS','medium','Addai is the traditional apostolic founder placed at the head of the Syriac line.'),
 ('ENT_SYR_BABAI','taught_by','ENT_SYR_NARSAI','medium','Babai the Great''s dyophysite theology continues the Antiochene-Nisibene school transmitted through Narsai''s School of Nisibis (Baum-Winkler).'),
 ('ENT_SYR_EPHREM','opposes','ENT_MANICH_MANI','high','Ephrem''s Prose Refutations and hymns explicitly polemicize against Mani and the Manichaeans (Brock).'),
 ('ENT_SYR_EPHREM','opposes','ENT_SYR_BARDAISAN','high','Ephrem composed hymns against the teaching of Bardaisan and his son Harmonius (Brock).'),
 ('ENT_SYR_FATHERS','reception_of','ENT_JESUS_CHRIST','high','The Syriac Fathers articulate Christian theology and devotion centered on Jesus Christ, preserved in his own Aramaic tongue.'),
 ('ENT_SYR_ISAAC_NINEVEH','aligned_with','ENT_SAINT_ANTHONY_ABBOT','medium','Isaac of Nineveh''s ascetical mysticism stands in the desert-monastic tradition typified by Anthony the Great.'),
 ('ENT_SYR_EPHREM','aligned_with','ENT_ORTH_BASIL','low','Later tradition links Ephrem with Basil the Great (a legendary meeting); both received as ecumenical doctors.');
